import json as _j

def _load(v):
    if isinstance(v, str):
        try:
            return _j.loads(v)
        except Exception:
            return None
    return v

def _digits(s):
    names = ["sıfır", "bir", "iki", "üç", "dört", "beş", "altı", "yedi", "sekiz", "dokuz"]
    return " ".join(names[int(c)] for c in str(s) if c.isdigit())

try:
    cards = _load(vars.get("cards"))
    raw = _load(vars.get("fetch_cards_response"))
    rawtxt = _j.dumps(raw, ensure_ascii=False) if raw is not None else ""
    if not isinstance(cards, list) and isinstance(raw, dict):
        d = raw.get("data") if isinstance(raw.get("data"), dict) else raw
        inner = d.get("data") if isinstance(d.get("data"), dict) else d
        cards = inner.get("cards") if isinstance(inner, dict) else None
    if isinstance(cards, list) and len(cards) > 0:
        main = [c for c in cards if c.get("isMainCard") is not False]
        vars["cards_status"] = "one" if len(cards) == 1 and len(main) == 1 else "many"
        lines = []
        for i, c in enumerate(cards):
            nm = (c.get("productName") or "").strip()
            l4 = str(c.get("cardNumberLast4") or str(c.get("cardNumber"))[-4:])
            num = str(c.get("cardNumber") or "")
            first6 = num[:6]
            same_name = len([x for x in cards if (x.get("productName") or "").strip() == nm]) > 1
            same4 = len([x for x in cards if str(x.get("cardNumberLast4")) == l4]) > 1
            ln = "Card " + str(i + 1) + ": name '" + (nm or "(no name; call it: sonu " + l4 + " ile biten kartınız)") + "', last four " + l4 + " (say: " + _digits(l4) + "), cardNumber for tools: " + num
            if c.get("isMainCard") is False:
                ln += ", SUPPLEMENTARY card: not eligible; say there is no eligible card for this and ask them to choose another"
            if same_name:
                ln += ", SAME NAME as another card: ask the last four digits"
            if same4:
                ln += ", SAME LAST FOUR as another card: ask the last six digits (its last six differ by the digits before the last four; this card's number starts " + first6 + ", never say this)"
            lines.append(ln)
        vars["card_facts"] = "\n".join(lines)
        names = []
        for c in main:
            nm = (c.get("productName") or "").strip()
            if nm and nm not in names and len(nm) < 40 and "talimat" not in nm.lower():
                names.append(nm)
        ex = names[:2]
        if len(ex) >= 2:
            q = "Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, " + ex[0] + " veya " + ex[1] + " diyebilirsiniz."
        elif len(ex) == 1:
            q = "Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, " + ex[0] + " diyebilirsiniz."
        else:
            q = "Hangi kartınızın borcunu öğrenmek istersiniz?"
        vars["card_question"] = q
        vars["single_card"] = str(cards[0].get("cardNumber") or "") if vars["cards_status"] == "one" else ""
    elif "FB_IVR_CHANNEL_102" in rawtxt or "404" in rawtxt[:0] :
        vars["cards_status"] = "none"
    else:
        vars["cards_status"] = "error"
    if vars.get("cards_status") == "error" and isinstance(raw, dict):
        sc = str(raw.get("status_code") or "")
        if sc == "404":
            vars["cards_status"] = "none"
except Exception as e:
    vars["cards_status"] = "error"
    vars["card_facts"] = ""

