import json as _j
import datetime as _dt

def _load(v):
    if isinstance(v, str):
        try:
            return _j.loads(v)
        except Exception:
            return None
    return v

def _inner(v):
    v = _load(v)
    if not isinstance(v, dict):
        return None
    d = v.get("data") if isinstance(v.get("data"), dict) else None
    if d is None:
        return None
    if isinstance(d.get("data"), dict):
        return d.get("data")
    if "result" in d:
        return None
    return d

_ON = ["", "bir", "iki", "üç", "dört", "beş", "altı", "yedi", "sekiz", "dokuz"]
_TEN = ["", "on", "yirmi", "otuz", "kırk", "elli", "altmış", "yetmiş", "seksen", "doksan"]

def _w3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(("" if h == 1 else _ON[h] + " ") + "yüz")
    if t:
        s.append(_TEN[t])
    if o:
        s.append(_ON[o])
    return " ".join(s)

def words(n):
    n = int(n)
    if n == 0:
        return "sıfır"
    parts = []
    for val, nm in ((10 ** 9, "milyar"), (10 ** 6, "milyon"), (1000, "bin")):
        q, n = divmod(n, val)
        if q:
            if val == 1000 and q == 1:
                parts.append("bin")
            else:
                parts.append(_w3(q) + " " + nm)
    if n:
        parts.append(_w3(n))
    return " ".join(parts)

UNIT = dict(TL=("Türk Lirası", "lira", "kuruş"), USD=("Dolar", "dolar", "sent"), EUR=("Euro", "euro", "sent"), GBP=("İngiliz Sterlini", "sterlin", "peni"))

def amount(x, cur):
    x = round(abs(float(x)) + 1e-9, 2)
    whole = int(x)
    frac = int(round((x - whole) * 100))
    full, main, sub = UNIT[cur]
    if frac == 0:
        return words(whole) + " " + full
    return words(whole) + " " + main + " " + words(frac) + " " + sub

AY = ["", "Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"]

def pdate(s):
    try:
        d, m, y = str(s).strip().split(".")
        return _dt.date(int(y), int(m), int(d))
    except Exception:
        return None

def sdate(d):
    return str(d.day) + " " + AY[d.month] + " " + str(d.year)

def joinlist(xs):
    if len(xs) == 1:
        return xs[0]
    return ", ".join(xs[:-1]) + " ve " + xs[-1]

def num(b, k):
    try:
        return float(b.get(k) or 0)
    except Exception:
        return 0.0

try:
    now = str(vars.get("now") or "")
    try:
        today = _dt.date(int(now[0:4]), int(now[5:7]), int(now[8:10]))
    except Exception:
        today = _dt.date.today()
    bal = None
    for k in ("cards_balance_response", "fetch_balance_response"):
        b = _inner(vars.get(k))
        if isinstance(b, dict) and ("debtTL" in b or "statementPaymentStatus" in b):
            bal = b
            break
    em = _inner(vars.get("fetch_email_response"))
    email = ""
    if isinstance(em, dict):
        email = str(em.get("ibanEmail") or "").strip()
        if str(em.get("communicationType") or "") == "Phone":
            email = ""
    vars["registered_email"] = email
    if not email:
        vars["email_facts"] = "There is NO registered e-mail address (or it could not be read). Never offer e-mail. If asked: \"Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum.\""
    else:
        local = email.split("@")[0]
        dom = email.split("@")[-1]
        messy = len(local) > 14 or sum(1 for c in local if c.isdigit() or c in "-_.") > 1
        say = (local[0] + " ile başlayan " + dom.split(".")[0] + " adresiniz") if messy else email
        vars["email_facts"] = "Registered e-mail: " + email + " (use it as emailAddress). Say it as: " + say + ". Ask: \"Ekstrenizi " + say + " adresine göndermemi ister misiniz?\""
    if not isinstance(bal, dict):
        vars["reading"] = ""
        vars["reading_ok"] = "no"
    else:
        name = str(bal.get("productName") or "").strip()
        l4 = str(bal.get("cardNumberLast4") or "")
        intro = "Sonu " + l4 + " ile biten " + (name + " kartınıza ait" if name else "kartınıza ait")
        intro2 = "Sonu " + l4 + " ile biten " + (name + " kartınızın" if name else "kartınızın")
        sd = pdate(bal.get("statementDate"))
        dd = pdate(bal.get("lastPayDate"))
        nsd = pdate(bal.get("nextStatementDate"))
        ndd = pdate(bal.get("nextLastPayDate"))
        blocks = []
        for cur, key in (("TL", "debtTL"), ("USD", "debtUSD"), ("EUR", "debtEUR"), ("GBP", "debtGBP")):
            b = bal.get(key)
            if isinstance(b, dict) and len(b) > 0:
                blocks.append((cur, b))
        out = []
        if sd is None:
            out.append("Kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.")
            if nsd is not None:
                out.append("İlk hesap kesim tarihiniz " + sdate(nsd) + " olacak.")
        elif (nsd is not None and nsd == today) or (dd is not None and today > dd):
            if nsd is not None and nsd == today:
                out.append("Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.")
            else:
                out.append(intro2 + " " + sdate(sd) + " tarihli ekstresinin son ödeme tarihi " + sdate(dd) + " geçmiştir.")
            owe = []
            clear = []
            for cur, b in blocks:
                t = num(b, "totalDebt")
                if t > 0:
                    owe.append(UNIT[cur][0] + " " + amount(t, cur))
                else:
                    clear.append(UNIT[cur][0])
            if owe:
                out.append(intro + " gelecek dönemler dahil toplam borcunuz: " + ", ".join(owe) + ".")
            if clear:
                out.append(joinlist(clear) + " borcunuz bulunmamaktadır.")
            if dd is not None and today > dd and str(bal.get("automaticPaymentFlag")) == "Y":
                tb = dict(blocks).get("TL")
                ra = num(tb, "remainAutomaticPaymentAmount") if tb else 0
                if ra > 0:
                    out.append("Otomatik ödeme talimatınızdan tahsil edilecek kalan tutar " + amount(ra, "TL") + ".")
        elif str(bal.get("statementPaymentStatus")) == "NO_DEBT":
            tb = dict(blocks).get("TL")
            total = num(tb, "totalDebt") if tb else 0.0
            if total < 0:
                total = 0.0
            out.append(intro2 + " " + sdate(sd) + " tarihli ekstresinden borcunuz bulunmamaktadır.")
            out.append("Gelecek dönemler dahil toplam borcunuz " + amount(total, "TL") + "'dir.")
            if dd is not None:
                out.append("Son ödeme tarihiniz " + sdate(dd) + " olacaktır.")
        else:
            first = True
            clear = []
            owe_lines = []
            for cur, b in blocks:
                rd = num(b, "remainingDebt")
                sdebt = num(b, "statementDebt")
                if rd <= 0 or sdebt <= 0:
                    clear.append(UNIT[cur][0])
                    continue
                full = UNIT[cur][0]
                mp = num(b, "minPayment")
                rmp = num(b, "remainingMinPayment")
                if cur == "TL":
                    if rmp > 0 and rmp >= mp:
                        s = "Türk Lirası borcunuz " + amount(sdebt, cur) + ", ödenmesi gereken minimum tutar " + amount(mp, cur) + "'dir."
                    elif rmp <= 0:
                        s = "Türk Lirası borcunuz " + amount(sdebt, cur) + ", kalan toplam borcunuz " + amount(rd, cur) + "'dir. Minimum ödemenizi yaptığınız için teşekkür ederiz."
                    else:
                        s = "Türk Lirası borcunuz " + amount(sdebt, cur) + ", ödenmesi gereken minimum tutar " + amount(mp, cur) + ", kalan toplam borcunuz " + amount(rd, cur) + ", kalan minimum ödeme tutarınız " + amount(rmp, cur) + "'dir."
                else:
                    s = full + " borcunuz " + amount(sdebt, cur) + ", kalan toplam borcunuz " + amount(rd, cur) + ", ödenmesi gereken minimum tutar " + amount(mp, cur) + "'dir."
                if first:
                    s = intro + " " + sdate(sd) + " tarihinde kesilen ekstre " + s
                    first = False
                owe_lines.append(s)
            out.extend(owe_lines)
            if clear and owe_lines:
                out.append(joinlist(clear) + " borcunuz bulunmamaktadır.")
            if dd is not None:
                if dd == today:
                    out.append("Borçlarınız için son ödeme tarihiniz bugündür.")
                else:
                    out.append("Borçlarınız için son ödeme tarihiniz " + sdate(dd) + "'dir.")
        vars["reading"] = " ".join(out)
        vars["reading_ok"] = "yes"
        vars["statement_date_raw"] = str(bal.get("statementDate") or "")
        vars["balance_facts"] = "Card just read: last four " + l4 + ", name '" + name + "', statementDate (for statement.pdf.send) " + str(bal.get("statementDate") or "none") + ", due date " + (sdate(dd) if dd else "none") + "."
    many = str(vars.get("cards_status")) == "many"
    can_week = True
    if email and can_week:
        offer = "Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim."
    else:
        offer = "Hesap kesim tarihinizi değiştirebilirim."
    vars["offer_line"] = offer
    vars["next_question"] = "Başka bir kartınızın borcunu öğrenmek ister misiniz?" if many else offer
except Exception as e:
    vars["reading"] = ""
    vars["reading_ok"] = "no"
    vars["offer_line"] = "Hesap kesim tarihinizi değiştirebilirim."
    vars["next_question"] = vars["offer_line"]

